example.code:
{
  "activation_event": "project_created",
  "window_days": 7,
  "dropoffs": [
    {"step": "project created", "screen": "/projects/new", "current_conversion": 0.326, "live_tactic": false},
    {"step": "email verified", "screen": "/verify", "current_conversion": 0.73, "live_tactic": false},
    {"step": "workspace named", "screen": "/workspace/setup", "current_conversion": 0.94, "live_tactic": true}
  ],
  "tactics": [
    {
      "id": "t1", "type": "checklist", "target_step": "project created", "step_conversion_baseline": 0.326,
      "checklist": {"items": [
        {"id": "workspace_named", "label": "Name your workspace", "required": false, "activation_event": false, "action": null, "tracked_event": "workspace_named"},
        {"id": "first_project", "label": "Create your first project", "required": true, "activation_event": true, "action": "/projects/new", "tracked_event": "project_created"},
        {"id": "invite", "label": "Invite a team member", "required": false, "activation_event": false, "action": "/team/invite", "tracked_event": "invite_sent"}
      ]}
    },
    {
      "id": "t2", "type": "email_sequence", "target_step": "email verified", "step_conversion_baseline": 0.73,
      "emails": [
        {"day": 0, "subject": "Verify your email to open your workspace", "cta_count": 1, "cta_url": "https://app.acme.com/verify?token={{token}}", "expected_time_minutes": 1, "send_condition": "always", "condition_evaluated_at": "send_time"},
        {"day": 1, "subject": "One click and your first project is 2 minutes away", "cta_count": 1, "cta_url": "https://app.acme.com/verify?token={{token}}", "expected_time_minutes": 1, "send_condition": "not_activated", "condition_evaluated_at": "send_time"},
        {"day": 3, "subject": "Need a hand getting in?", "cta_count": 1, "cta_url": "https://app.acme.com/verify?token={{token}}", "expected_time_minutes": 1, "send_condition": "not_activated", "condition_evaluated_at": "send_time"}
      ]
    }
  ],
  "steps": [
    {"id": "s1", "tactic_id": "t1", "action": "Ship the 3-item checklist on /projects/new to 100 percent of new signups for two closed signup weeks", "exit_criterion": {"metric": "step_conversion", "baseline": 0.326, "minimum_lift": 0.03}, "output_location": "growth/activation/2026-05-checklist.md"},
    {"id": "s2", "tactic_id": "t2", "action": "Enable the 3-send verification sequence with send-time suppression for two closed signup weeks", "exit_criterion": {"metric": "step_conversion", "baseline": 0.73, "minimum_lift": 0.05}, "output_location": "growth/activation/2026-05-verify-emails.md"}
  ],
  "decision_branches": [
    {"kind": "defer_live_tactic", "when": "the target step already has a live tactic in this period (workspace named)", "then": "defer the new tactic until the live one has hit or missed its exit criterion"},
    {"kind": "remove", "when": "step conversion after two closed weeks is below baseline plus minimum_lift", "then": "remove the tactic and return to the drop-off ranking"},
    {"kind": "keep", "when": "step conversion after two closed weeks is at or above baseline plus minimum_lift", "then": "keep the tactic and move to the next drop-off step"}
  ]
}

{
  "activation_event": "project_created",
  "window_days": 7,
  "dropoffs": [
    {"step": "project created", "screen": "/projects/new", "current_conversion": 0.326, "live_tactic": false}
  ],
  "tactics": [
    {
      "id": "t1", "type": "checklist", "target_step": "onboarding", "step_conversion_baseline": 0.5,
      "checklist": {"items": [
        {"id": "profile", "label": "Complete your profile", "required": false, "activation_event": false, "action": "/settings/profile", "tracked_event": null},
        {"id": "read_docs", "label": "Read the getting-started guide", "required": false, "activation_event": false, "action": null, "tracked_event": null},
        {"id": "first_project", "label": "Create your first project", "required": false, "activation_event": true, "action": "/projects/new", "tracked_event": "project_created"},
        {"id": "invite", "label": "Invite a team member", "required": false, "activation_event": true, "action": "/team/invite", "tracked_event": "invite_sent"},
        {"id": "watch_video", "label": "Watch the intro video", "required": false, "activation_event": false, "action": null, "tracked_event": null},
        {"id": "connect", "label": "Connect an integration", "required": false, "activation_event": false, "action": "/integrations", "tracked_event": null}
      ]}
    },
    {
      "id": "t2", "type": "email_sequence", "target_step": "project created", "step_conversion_baseline": 0.326,
      "emails": [
        {"day": 0, "subject": "Welcome to Acme", "cta_count": 2, "cta_url": "https://app.acme.com/", "expected_time_minutes": 2, "send_condition": "always", "condition_evaluated_at": "send_time"},
        {"day": 3, "subject": "Quick win: do this in 5 minutes", "cta_count": 1, "cta_url": "https://app.acme.com/login", "expected_time_minutes": 5, "send_condition": "always", "condition_evaluated_at": "send_time"},
        {"day": 10, "subject": "Your account is waiting", "cta_count": 1, "cta_url": "https://app.acme.com/projects/new", "expected_time_minutes": 2, "send_condition": "not_activated", "condition_evaluated_at": "send_time"}
      ]
    },
    {
      "id": "t3", "type": "in_app_guide", "target_step": "project created", "step_conversion_baseline": 0.326,
      "guide": {"screen": "/dashboard", "guides_on_screen": 3, "dismissible_in_one_click": true, "hidden_after_step_complete": false}
    }
  ],
  "steps": [
    {"id": "s1", "tactic_id": "t1", "action": "Ship the checklist to everyone", "exit_criterion": {"metric": "step_conversion", "baseline": 0.5, "minimum_lift": 0.02}, "output_location": "docs/published/"}
  ],
  "decision_branches": [
    {"kind": "loop_back", "when": "activation does not improve", "then": "try another tactic from the list"}
  ]
}
